FP.copy=x=>JSON.parse(JSON.stringify(x));
FP.mapFor=(feature,option=0,level=0,dateKey='')=>{
 let index=(level+(feature.id==='ghost'?option:0))%FP.maps.length;
 if(['food','garden','travel','mouth','office'].includes(feature.id))index=level%3;
 if(feature.id==='office')index=(level+option)%6;
 if(feature.id==='duel')index=level+(option?3:0);
 if(feature.id==='daily')index=[...dateKey].reduce((a,x)=>a+x.charCodeAt(0),0)%6;
 const m=FP.copy(FP.maps[index]);m.theme=feature.theme;
 if(feature.id==='sleep'&&level>=6){for(const key of ['ball','hole'])m[key].x=760-m[key].x;for(const key of ['walls','sand','water'])m[key].forEach(r=>r.x=760-r.x-r.w);m.stars.forEach(p=>p.x=760-p.x);m.name='星光另一边 · '+(level+1);}
 if(feature.id==='travel')m.theme=['garden','coast','snow'][option];
 if(feature.id==='sleep')m.theme=['night','coast','garden'][option];
 if(['puzzle','ghost','daily','relay','duel','sleep'].includes(feature.id))m.stars=[];
 m.id=`${feature.id}-${option}-${level}-${dateKey}`;
 return m;
};
